draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20 + 10*Math.sin(t), 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20 + 10*Math.sin(t));
  ctx.lineTo(W/2, H);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 10 - 5*Math.sin(t), H/2 + 40 + 10*Math.sin(t));
  ctx.lineTo(W/2, H/2 + 20 + 10*Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 10 + 5*Math.sin(t), H/2 + 40 + 10*Math.sin(t));
  ctx.lineTo(W/2, H/2 + 20 + 10*Math.sin(t));
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('TRUNK', W/2, H/2 - 30 - 10*Math.sin(t));
  ctx.restore();
}
